insert into social_content_queue
  (day_number, slot_number, scheduled_time, platform, format, theme, caption, image_search_term)
values
  (1, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Tokyo, if you know you know. 🌆 Shinjuku Station moves 3 MILLION people a day — and somewhere in that crowd, someone''s proud to call it home. Tag a Tokyoite. #glotemp #Tokyo #CityPulse', 'Tokyo skyline or Shinjuku crossing, wide shot, golden hour if available'),
  (1, 2, '14:00', 'instagram', 'Carousel (2-3 slides)', 'Vertical: Property', 'What does ''home'' actually feel like in London right now? Our Property read isn''t a headline number — it''s the real pulse of a city''s housing energy, live. Swipe for the read. →', 'Slide 1: London skyline. Slide 2: residential street. Slide 3: branded pulse-reading graphic'),
  (1, 3, '19:00', 'instagram', 'Single image', 'Emotional/Pulse', 'A city doesn''t stop when you leave it. Its clock, its sky, its radio still run. glo-temp.com — the city you left is still going. 🌍', 'Sunset city skyline, could be any flagship city — pick most visually striking available that week'),
  (2, 1, '09:00', 'instagram', 'Single image', 'City pride', 'If you''ve ever ridden the Underground, you''ve ridden history — 1863, world''s first. London, this one''s for you. Tag someone who calls this city home. #glotemp #London', 'Underground platform or iconic red bus + Big Ben composite'),
  (2, 2, '14:00', 'instagram', 'Reel/short video concept', 'Vertical: Food', 'Manila''s food scene doesn''t sleep. Adobo at noon, lechon by night — this is what ''local'' actually tastes like. What''s YOUR city''s dish? Comment below. 🍽️', 'Food market or street food stall, Manila'),
  (2, 3, '19:00', 'instagram', 'Single image', 'Engagement', 'Real question: which city''s weather would surprise you most right now? Drop your guess. 👇', 'Weather-themed graphic overlay on a city photo (rain, sun, or snow depending on live read)'),
  (3, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Manila: 20 million people, one of the densest cities on Earth, and still standing tall. If this is home, you already know. #glotemp #Manila', 'Manila skyline, dense urban shot'),
  (3, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Tech', 'Bangalore isn''t just India''s tech capital on paper — it''s alive with it. Our Tech read tracks real developer activity, city by city. Swipe to see how it''s measured. →', 'Slide 1: Bangalore tech district. Slide 2: branded data visualization'),
  (3, 3, '19:00', 'instagram', 'Single image', 'Pulse', 'Weather apps tell you the sky. glo-temp.com tells you the whole city. 🌤️', 'Split image: weather icon vs. full city ''pulse'' graphic'),
  (4, 1, '09:00', 'instagram', 'Single image', 'City pride', '950 bridges. More than Venice. Berlin, you don''t get enough credit for this. Tag a Berliner. #glotemp #Berlin', 'Berlin bridge/river shot, iconic if possible (Oberbaum Bridge)'),
  (4, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Transport', 'Rush hour tells you everything about a city''s mood. Our Transport read captures that shift, live. Swipe for how NYC is reading right now. →', 'Slide 1: NYC subway/traffic. Slide 2: branded pulse graphic'),
  (4, 3, '19:00', 'instagram', 'Single image', 'Emotional', 'Somewhere, right now, a city is waking up. Somewhere else, one is going quiet. glo-temp.com reads all 300 — live. 🌙', 'Split-screen: sunrise city / nighttime city'),
  (5, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Singapore''s Changi has a literal butterfly garden inside the airport. If this is home, that''s just Tuesday for you. #glotemp #Singapore', 'Changi Airport interior or Singapore skyline (Marina Bay)'),
  (5, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Transport', 'Some cities flow. Some cities fight for every inch. Our Transport read shows you which is which, before you land. →', 'Slide 1: busy intersection. Slide 2: branded graphic'),
  (5, 3, '19:00', 'instagram', 'City vs. City (PREVIEW)', 'Engagement', 'Tomorrow: our first City vs. City. Two cities, one crown. Who''s ready? 👀', 'Teaser graphic: silhouettes of two city skylines facing off'),
  (6, 1, '09:00', 'instagram', 'Single image', 'City pride', 'NYC''s subway never fully stops — 24/7, 365 days a year. If this is home, you''ve probably slept through the 3am train at least once. #glotemp #NYC', 'Iconic NYC subway or skyline shot'),
  (6, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Work', 'Hiring pulse shifts week to week — not quarter to quarter. Our Work read is built to actually keep up. Swipe for this week''s read. →', 'Slide 1: coworking space or business district. Slide 2: branded graphic'),
  (6, 3, '19:00', 'instagram', 'CITY VS CITY', 'Bracket event', '⚔️ TOKYO vs. LONDON — Round 1 ⚔️ Two legendary cities, one live pulse read. ❤️ for Tokyo. 🔥 for London. Winner announced Monday.', 'Split-image carousel or single composite: Tokyo skyline left, London skyline right, VS graphic center'),
  (7, 1, '09:00', 'instagram', 'Single image', 'City pride', '200+ distinct neighbourhoods, each with its own personality. Toronto, you contain multitudes. Tag someone from here. #glotemp #Toronto', 'Toronto skyline (CN Tower) or neighbourhood street shot'),
  (7, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Entertainment', 'Big events change a city''s whole rhythm. Our Entertainment read catches that shift as it happens. Swipe to see this week''s energy. →', 'Slide 1: concert/event crowd. Slide 2: branded graphic'),
  (7, 3, '19:00', 'instagram', 'Single image', 'Pulse', 'Week one down. 293 more cities to go. glo-temp.com — know how a city feels before you go.', 'Brand card, minimal, month-1 milestone framing'),
  (8, 1, '09:00', 'instagram', 'Single image', 'City pride', 'The Coathanger. That''s what Sydney locals call the Harbour Bridge — and they say it with love. Tag a Sydneysider. #glotemp #Sydney', 'Sydney Harbour Bridge + Opera House classic shot'),
  (8, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Education', 'Campus energy is one of the most distinct pulses a city can have. We''re building toward reading it properly. Swipe to see why. →', 'Slide 1: university campus. Slide 2: branded graphic'),
  (8, 3, '19:00', 'instagram', 'BRACKET RESULT', 'Bracket event', '🏆 TOKYO takes Round 1! London, we see you plotting a comeback. Next matchup Friday. Who do you want to see face off?', 'Winner graphic: Tokyo skyline with ''WINNER'' badge'),
  (9, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Bangalore: India''s Silicon Valley, and one of the most genuinely alive tech scenes anywhere. If this is home, you''re already building something. #glotemp #Bangalore', 'Bangalore tech park or street scene'),
  (9, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Finance', 'Economic energy isn''t a quarterly report — it''s a weekly pulse. Swipe to see how we''re reading it now. →', 'Slide 1: financial district. Slide 2: branded graphic'),
  (9, 3, '19:00', 'instagram', 'Single image', 'Emotional', 'You''ve checked the weather. Now check the city. glo-temp.com — mood, radio, press, pulse, live. 🌍', 'Brand card or collage of multiple city clocks'),
  (10, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Helsinki: ranked one of the world''s happiest cities, years running. If this is home, you already knew that. #glotemp #Helsinki', 'Helsinki waterfront or cityscape, soft light'),
  (10, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Health', 'A city''s health pulse is more than hospital stats — it''s the everyday feel of a place. We''re working toward reading that honestly. →', 'Slide 1: park/green space. Slide 2: branded graphic'),
  (10, 3, '19:00', 'instagram', 'Single image', 'Pulse', 'Some cities are loud today. Some are quiet. glo-temp.com reads both, live, without judgment.', 'Contrast image: bustling street vs. quiet park, split composite'),
  (11, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Seoul has some of the fastest average internet speeds of any major city on Earth. If this is home, you probably never think about buffering. #glotemp #Seoul', 'Seoul skyline (Han River or N Seoul Tower)'),
  (11, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Sport', 'Match days change a city''s whole rhythm. Our Sport read is built to capture that shift. Swipe for this week''s energy. →', 'Slide 1: stadium/fans. Slide 2: branded graphic'),
  (11, 3, '19:00', 'instagram', 'Engagement', 'City pride', 'Two cities, one choice: would you rather land somewhere buzzing tonight, or somewhere dead calm? Comment your pick. 👇', 'Split image: nightlife street vs. quiet skyline'),
  (12, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Bangkok''s official name has over 160 letters. Yes, really. If this is home, you''ve never once said the whole thing. #glotemp #Bangkok', 'Bangkok skyline or Chao Phraya river'),
  (12, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Fashion', 'Style shifts block by block, season by season — never static. This is where that texture eventually lives on glo-temp.com. →', 'Slide 1: fashion district street style. Slide 2: branded graphic'),
  (12, 3, '19:00', 'instagram', 'BRACKET PREVIEW', 'Bracket event', 'Friday''s matchup: MANILA vs. BANGKOK. Two cities, endless energy, one crown. Get ready. 👀', 'Teaser: silhouette skylines, VS graphic'),
  (13, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Built on a former lakebed and sinking 20 inches a year in places — Mexico City doesn''t do anything small. If this is home, respect. #glotemp #MexicoCity', 'Mexico City skyline or Zocalo square'),
  (13, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Property', 'Rental pressure spikes and eases with the seasons. Our Property read is built to actually show that movement. Swipe for how. →', 'Slide 1: residential neighbourhood. Slide 2: branded graphic'),
  (13, 3, '19:00', 'instagram', 'Single image', 'Emotional', 'Right now, somewhere on glo-temp.com, someone just checked in on their hometown from 6,000 miles away. That''s the whole point. 🌍', 'Brand card, world map graphic with pulse points'),
  (14, 1, '09:00', 'instagram', 'Single image', 'City pride', 'São Paulo has more helicopters in regular use than almost anywhere on Earth. If this is home, that''s just how you beat the traffic. #glotemp #SãoPaulo', 'São Paulo skyline, dense high-rise shot'),
  (14, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Food', 'A city''s food scene is a live signal, not a fixed guidebook entry. Swipe to see what''s trending this week. →', 'Slide 1: street food/market. Slide 2: branded graphic'),
  (14, 3, '19:00', 'instagram', 'BRACKET RESULT', 'Bracket event', '🏆 MANILA wins the crown this round! Bangkok, you brought real heat. Next matchup Friday — vote who you want to see.', 'Winner graphic: Manila skyline with ''WINNER'' badge'),
  (15, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Chandni Chowk has been trading much as it has for centuries. Delhi, you carry history in your streets. Tag someone from here. #glotemp #Delhi', 'Chandni Chowk market or Delhi skyline'),
  (15, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Tech', 'Developer activity is a real, live signal — not a lagging report. Swipe to see how we track it. →', 'Slide 1: coding/tech meetup. Slide 2: branded graphic'),
  (15, 3, '19:00', 'instagram', 'Single image', 'Positioning', 'Halfway through the month. Still 300 cities. Still reading live. glo-temp.com. 🌍', 'Brand milestone card'),
  (16, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Over 500 buildings above 150 metres — Hong Kong''s skyline is basically unmatched. If this is home, you live in the clouds. #glotemp #HongKong', 'Hong Kong skyline, Victoria Harbour view'),
  (16, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Transport', 'Some cities move fast, some move slow — neither is wrong, but you should know which one you''re walking into. Swipe for the read. →', 'Slide 1: transit hub. Slide 2: branded graphic'),
  (16, 3, '19:00', 'instagram', 'Engagement', 'Emotional', 'You''ve noticed we check in on cities daily. Some of you have started checking in too — and we''ve noticed that. 💛', 'Warm brand card, subtle ''thank you'' framing'),
  (17, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Shanghai''s Maglev hits 430 km/h — airport to city in about 8 minutes. If this is home, everyone else''s ''fast train'' looks slow to you. #glotemp #Shanghai', 'Shanghai Maglev or skyline (Pudong)'),
  (17, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Work', 'Remote-friendly hiring signals move faster than most job boards update. Swipe to see this week''s read. →', 'Slide 1: coworking/remote work scene. Slide 2: branded graphic'),
  (17, 3, '19:00', 'instagram', 'BRACKET PREVIEW', 'Bracket event', 'Friday: BERLIN vs. SEOUL. Old-world energy vs. new-world speed. Who''s got your vote? 👀', 'Teaser: silhouette skylines, VS graphic'),
  (18, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Six official cats live inside the Louvre — historically kept to protect the art. Paris, only you. #glotemp #Paris', 'Louvre exterior or Paris skyline'),
  (18, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Entertainment', 'Festival season changes a city''s entire pulse. We''re starting to capture that shift, live. Swipe to see how. →', 'Slide 1: festival/event crowd. Slide 2: branded graphic'),
  (18, 3, '19:00', 'instagram', 'Single image', 'Emotional', 'A city you''ve never visited still has a pulse today. glo-temp.com lets you feel it before you ever book a flight. 🌍', 'Collage of multiple city skylines'),
  (19, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Berlin''s public transport genuinely runs 24 hours on weekends. If this is home, the party literally never has to end. #glotemp #Berlin', 'Berlin nightlife street or U-Bahn platform'),
  (19, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Education', 'University rhythm is a real, visible pulse shift — cities empty out and fill back up like clockwork. Swipe to see why we''re tracking it. →', 'Slide 1: campus quad. Slide 2: branded graphic'),
  (19, 3, '19:00', 'instagram', 'BRACKET RESULT + soft incentive intro', 'Bracket event', '🏆 SEOUL takes it! Berlin, that was close. Also — Founding Voices: the earliest people checking in on their cities are helping shape what this becomes. If that''s you, thank you.', 'Winner graphic + subtle ''Founding Voices'' badge intro'),
  (20, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Toronto''s PATH network runs 30km underground — built partly to survive the winters. If this is home, you''ve never once needed a coat downtown. #glotemp #Toronto', 'Toronto PATH interior or winter skyline'),
  (20, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Health', 'City energy and wellbeing are more connected than most data shows. We''re working toward a read that reflects that honestly. →', 'Slide 1: park/wellness scene. Slide 2: branded graphic'),
  (20, 3, '19:00', 'instagram', 'Engagement', 'Emotional', 'Does a city''s mood actually change how you''d plan a trip there? We think it should. Curious what you think. 👇', 'Warm brand card, question overlay'),
  (21, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Sydney Opera House took 14 years longer and 15x the budget — now it''s unmistakable. If this is home, that''s basically main character energy. #glotemp #Sydney', 'Sydney Opera House iconic shot'),
  (21, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Sport', 'Big match tonight? Our Sport read catches that shift in a city''s energy before, during, and after. Swipe for the live read. →', 'Slide 1: stadium exterior. Slide 2: branded graphic'),
  (21, 3, '19:00', 'instagram', 'BRACKET PREVIEW', 'Bracket event', 'Friday: SYDNEY vs. TORONTO. Two continents, one crown. Get your votes ready. 👀', 'Teaser: silhouette skylines, VS graphic'),
  (22, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Singapore''s strict on chewing gum but world-class on transit. If this is home, you''ve made peace with the tradeoff. #glotemp #Singapore', 'Singapore MRT or Gardens by the Bay'),
  (22, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Finance', 'A city''s economic pulse shifts week to week. Our Finance read is built to actually catch that. Swipe for this week''s read. →', 'Slide 1: financial district. Slide 2: branded graphic'),
  (22, 3, '19:00', 'instagram', 'Full incentive CTA', 'Emotional', 'Founding Voices get first access as our sponsor rewards roll out — hotel stays, vouchers, partner perks. Check in on your city today, be first in line. 💛', 'Warm brand card, ''Founding Voices'' framing front and center'),
  (23, 1, '09:00', 'instagram', 'Single image', 'City pride', '20 million people in greater Manila — one of the densest urban regions on Earth. If this is home, you already know how alive it feels. #glotemp #Manila', 'Manila dense skyline shot'),
  (23, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Property', 'Housing pressure is a felt thing, not just a headline number. Swipe to see how our Property read captures that texture. →', 'Slide 1: residential street. Slide 2: branded graphic'),
  (23, 3, '19:00', 'instagram', 'BRACKET RESULT', 'Bracket event', '🏆 SYDNEY wins! Toronto, you made it close. Next round Friday — comment who YOU want to see face off.', 'Winner graphic with badge'),
  (24, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Bangkok''s khlongs (canals) were the city''s original highways before roads took over. If this is home, water runs through everything you know. #glotemp #Bangkok', 'Bangkok canal/khlong scene'),
  (24, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Food', 'Lunch energy is not dinner energy — street food scenes shift with the hour. Swipe to see what''s trending right now. →', 'Slide 1: street food stall, daytime. Slide 2: branded graphic'),
  (24, 3, '19:00', 'instagram', 'Single image', 'Positioning', 'glo-temp.com isn''t trying to replace a guidebook. It''s trying to replace the guesswork. 300 cities, live. 🌍', 'Clean brand card'),
  (25, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Shibuya Crossing moves up to 3,000 people per light change. Tokyo, that''s basically choreography. If this is home, you''ve mastered the flow. #glotemp #Tokyo', 'Shibuya Crossing aerial or street-level shot'),
  (25, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Tech', 'Some cities are quietly building faster than the headlines suggest. Swipe to see how our Tech read surfaces that. →', 'Slide 1: tech district. Slide 2: branded graphic'),
  (25, 3, '19:00', 'instagram', 'Incentive CTA', 'Emotional', 'Founding Voices — check in on your city, and you''re first in line as sponsor rewards roll out. Real perks, real partners, coming soon. 💛', 'Warm brand card, community framing'),
  (26, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Central Park is bigger than the entire country of Monaco. NYC, only you could make that true. Tag a New Yorker. #glotemp #NYC', 'Central Park aerial or iconic skyline-with-park shot'),
  (26, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Transport', 'Rush hour mood is its own kind of pulse — some cities handle it calmly, some don''t. Swipe to see the difference. →', 'Slide 1: rush hour street. Slide 2: branded graphic'),
  (26, 3, '19:00', 'instagram', 'BRACKET PREVIEW', 'Bracket event', 'Friday: PARIS vs. BERLIN. Old rivals, new format. Who''s got your vote? 👀', 'Teaser: silhouette skylines, VS graphic'),
  (27, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Seoul''s subway has some of the widest free WiFi coverage of any transit system on Earth. If this is home, you''ve never once lost signal underground. #glotemp #Seoul', 'Seoul subway platform or skyline'),
  (27, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Work', 'Hiring pulse shifts fast in tech-heavy cities — sometimes week to week. Swipe for this week''s read. →', 'Slide 1: business district. Slide 2: branded graphic'),
  (27, 3, '19:00', 'instagram', 'Single image', 'Positioning', 'Every city has a story happening right now, not just the ones in headlines. glo-temp.com reads all 300 of them, live. 🌍', 'Collage of multiple city skylines'),
  (28, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Three UNESCO World Heritage Sites, all within the city — Red Fort, Qutub Minar, Humayun''s Tomb. Delhi, you''re basically a living museum. #glotemp #Delhi', 'Red Fort or Qutub Minar shot'),
  (28, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Education', 'Campus energy is one of the most distinct pulses a city can have. Swipe to see why we''re building toward reading it. →', 'Slide 1: university building. Slide 2: branded graphic'),
  (28, 3, '19:00', 'instagram', 'BRACKET RESULT + incentive', 'Bracket event', '🏆 PARIS takes the crown! Berlin, you''ll get your rematch. Also — Founding Voices, check in today: early contributors get first access as sponsor rewards roll out.', 'Winner graphic + Founding Voices reminder badge'),
  (29, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Hong Kong''s ''Ding Ding'' tram has been running since 1904. If this is home, you''ve heard that bell your whole life. #glotemp #HongKong', 'Hong Kong tram, classic street shot'),
  (29, 2, '14:00', 'instagram', 'Carousel', 'Vertical: Entertainment', 'Big events change a city''s whole rhythm for days, not hours. Swipe to see how we catch that shift. →', 'Slide 1: event/concert crowd. Slide 2: branded graphic'),
  (29, 3, '19:00', 'instagram', 'Engagement', 'Emotional', 'One month of daily reads. Genuinely — what''s kept you checking in? Comment below, we read every one. 💛', 'Warm brand card, milestone framing'),
  (30, 1, '09:00', 'instagram', 'Single image', 'City pride', 'Shanghai''s skyline has more buildings over 200 metres than almost anywhere on the planet. If this is home, you look UP a lot. #glotemp #Shanghai', 'Shanghai skyline (Pudong), dramatic wide shot'),
  (30, 2, '14:00', 'instagram', 'Carousel', 'Positioning', 'One month down. 300 cities read, live, every single day. This was just the beginning. Swipe through a month of pulses. →', 'Slide 1-3: recap collage of featured cities this month'),
  (30, 3, '19:00', 'instagram', 'Full incentive + milestone', 'Emotional', 'Founding Voices, thank you for being early. Check in on your city — the earliest voices shape what this becomes, and the rewards are coming. glo-temp.com 💛🌍', 'Warm brand card, month-1 celebration framing')
